/* Token Radar: a dark, dense board for pre-token protocols. System fonts only, no network. */
:root {
  --bg: #070b10;
  --bg-2: #0a1018;
  --surface: #0f1721;
  --surface-2: #131d29;
  --surface-3: #172334;
  --border: #1d2a38;
  --border-2: #2a3b4d;
  --ink: #e8eff7;
  --muted: #91a6ba;
  --dim: #657a8e;
  --accent: #37dfc2;
  --accent-2: #35b7ff;
  --gold: #f4c45a;
  --pos: #46db9a;
  --neg: #ff7373;
  --warn: #f4a259;
  --radius: 14px;
  --radius-sm: 9px;
  --font: system-ui, -apple-system, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  --mono: ui-monospace, "SF Mono", "Cascadia Code", Menlo, Consolas, monospace;
}
* { box-sizing: border-box; }
html { color-scheme: dark; }
body {
  margin: 0;
  min-height: 100vh;
  color: var(--ink);
  font: 400 14px/1.45 var(--font);
  background:
    radial-gradient(1100px 560px at 82% -12%, rgba(53, 183, 255, 0.13), transparent 60%),
    radial-gradient(820px 480px at -6% 2%, rgba(55, 223, 194, 0.10), transparent 55%),
    var(--bg);
  -webkit-font-smoothing: antialiased;
  text-rendering: optimizeLegibility;
}
body.detail-open { overflow: hidden; }
h1, h2, h3 { margin: 0; letter-spacing: -0.02em; }
p { margin: 0; }
button, input, select { font: inherit; color: inherit; }
button { cursor: pointer; }
:focus-visible { outline: 2px solid var(--accent); outline-offset: 2px; }
.skip {
  position: absolute; left: -9999px; top: 0; z-index: 60; padding: 10px 16px;
  background: var(--surface); border: 1px solid var(--border); border-radius: var(--radius-sm);
}
.skip:focus { left: 16px; top: 16px; }

.shell { max-width: 1460px; margin: 0 auto; padding: 0 26px 56px; }

/* top bar */
.topbar {
  position: sticky; top: 0; z-index: 15;
  display: flex; align-items: center; justify-content: space-between; gap: 20px;
  height: 58px; margin: 0 -26px; padding: 0 26px;
  background: rgba(7, 11, 16, 0.82); backdrop-filter: blur(14px);
  border-bottom: 1px solid var(--border);
}
.brand { display: flex; align-items: center; gap: 12px; }
.logo {
  width: 22px; height: 22px; border-radius: 7px; flex: none;
  background: conic-gradient(from 210deg, var(--accent), var(--accent-2), var(--gold), var(--accent));
  box-shadow: 0 0 18px rgba(55, 223, 194, 0.35);
}
.brand-name { display: block; font-size: 14px; letter-spacing: 0.08em; text-transform: uppercase; }
.brand-sub { display: block; font-size: 11px; color: var(--dim); letter-spacing: 0.04em; }
.top-meta { display: flex; align-items: center; gap: 12px; color: var(--muted); font-size: 12px; white-space: nowrap; }
.top-meta .dot-sep { width: 3px; height: 3px; border-radius: 50%; background: var(--dim); }
.pill {
  border: 1px solid var(--border-2); border-radius: 999px; padding: 4px 10px;
  color: var(--accent); background: rgba(55, 223, 194, 0.07); font-size: 11px; letter-spacing: 0.03em;
}

/* hero */
.hero { display: grid; grid-template-columns: minmax(0, 1fr) auto; gap: 34px; align-items: end; padding: 28px 0 20px; }
.eyebrow { color: var(--accent); font-size: 11px; letter-spacing: 0.16em; font-weight: 600; margin-bottom: 8px; }
.hero h1 { font-size: 33px; line-height: 1.08; font-weight: 650; max-width: 820px; text-wrap: balance; }
.lede { color: var(--muted); max-width: 780px; margin-top: 12px; font-size: 14px; }
.stats { display: grid; grid-template-columns: repeat(5, minmax(112px, 1fr)); gap: 8px; }
.stat {
  background: linear-gradient(180deg, var(--surface-2), var(--surface));
  border: 1px solid var(--border); border-radius: var(--radius-sm); padding: 11px 12px;
}
.stat span { display: block; color: var(--dim); font-size: 10px; letter-spacing: 0.08em; text-transform: uppercase; }
.stat b { display: block; font-family: var(--mono); font-size: 18px; font-weight: 600; margin-top: 4px; }
.stat i { display: block; color: var(--muted); font-style: normal; font-size: 10px; margin-top: 2px; }

/* controls */
.controls {
  display: flex; flex-wrap: wrap; align-items: end; gap: 12px;
  padding: 14px; margin-bottom: 14px;
  background: rgba(15, 23, 33, 0.72); border: 1px solid var(--border); border-radius: var(--radius);
}
.seg { display: flex; gap: 3px; padding: 3px; border: 1px solid var(--border); border-radius: var(--radius-sm); background: var(--bg-2); align-self: center; }
.seg-btn { border: 0; background: transparent; color: var(--muted); border-radius: 7px; padding: 7px 11px; font-size: 12px; white-space: nowrap; }
.seg-btn.active { background: var(--surface-3); color: var(--ink); box-shadow: inset 0 0 0 1px var(--border-2); }
.field { display: grid; gap: 4px; }
.field label, .field .field-label { color: var(--dim); font-size: 10px; letter-spacing: 0.08em; text-transform: uppercase; }
.field input, .field select {
  height: 36px; border: 1px solid var(--border-2); border-radius: var(--radius-sm);
  background: var(--bg-2); padding: 0 11px; min-width: 170px; color: var(--ink);
}
.field input { min-width: 300px; }
.field input::placeholder { color: var(--dim); }
.toggle {
  display: inline-flex; align-items: center; gap: 9px; height: 36px; padding: 0 12px;
  border: 1px solid var(--border-2); border-radius: var(--radius-sm); background: var(--bg-2); color: var(--muted);
}
.toggle .track { width: 30px; height: 17px; border-radius: 999px; background: #243344; position: relative; flex: none; transition: background 150ms; }
.toggle .track::after { content: ""; position: absolute; left: 2px; top: 2px; width: 13px; height: 13px; border-radius: 50%; background: var(--muted); transition: transform 150ms, background 150ms; }
.toggle[aria-pressed="true"] { color: var(--ink); border-color: rgba(55, 223, 194, 0.55); }
.toggle[aria-pressed="true"] .track { background: rgba(55, 223, 194, 0.30); }
.toggle[aria-pressed="true"] .track::after { transform: translateX(13px); background: var(--accent); }
.ghost { height: 36px; padding: 0 12px; border: 1px solid var(--border-2); border-radius: var(--radius-sm); background: transparent; color: var(--muted); }
.ghost:hover { color: var(--ink); border-color: var(--muted); }
.count { margin-left: auto; align-self: center; color: var(--muted); font-size: 12px; }
.count b { color: var(--ink); font-family: var(--mono); }

/* panel and table */
.panel { background: linear-gradient(180deg, rgba(19, 29, 41, 0.92), rgba(15, 23, 33, 0.96)); border: 1px solid var(--border); border-radius: var(--radius); overflow: hidden; }
.panel-head { display: flex; align-items: end; justify-content: space-between; gap: 18px; padding: 16px 18px 13px; border-bottom: 1px solid var(--border); }
.panel-head h2 { font-size: 17px; font-weight: 600; }
.panel-sub { color: var(--muted); font-size: 12px; margin-top: 3px; }
.legend { display: flex; gap: 14px; color: var(--dim); font-size: 11px; white-space: nowrap; }
.legend-item { display: inline-flex; align-items: center; gap: 6px; }
.swatch { width: 14px; height: 5px; border-radius: 3px; display: inline-block; }
.swatch.implied { background: linear-gradient(90deg, var(--accent), var(--gold)); }
.swatch.conf { background: var(--accent-2); }
.table-wrap { overflow: auto; max-height: calc(100vh - 470px); }
table { width: 100%; border-collapse: collapse; }
thead th {
  position: sticky; top: 0; z-index: 5;
  background: var(--surface-2); color: var(--dim); font-size: 10px; font-weight: 600;
  letter-spacing: 0.09em; text-transform: uppercase; text-align: left;
  padding: 9px 12px; border-bottom: 1px solid var(--border-2); white-space: nowrap;
}
thead th.num, td.num { text-align: right; }
.sort-btn { display: inline-flex; align-items: center; gap: 5px; border: 0; background: none; padding: 0; color: inherit; font: inherit; letter-spacing: inherit; text-transform: inherit; }
.sort-btn:hover, .sort-btn.active { color: var(--accent); }
.arrow { font-size: 9px; }
tbody td { padding: 10px 12px; border-bottom: 1px solid rgba(29, 42, 56, 0.72); vertical-align: middle; }
tbody tr { cursor: pointer; transition: background 120ms; }
tbody tr:hover { background: rgba(23, 35, 52, 0.72); }
tbody tr[data-selected="true"] { background: rgba(55, 223, 194, 0.085); }
tbody tr:last-child td { border-bottom: 0; }
.rank-cell { width: 56px; }
.rank-num { font-family: var(--mono); color: var(--dim); font-size: 12px; }
.rank-num.top { color: var(--gold); font-weight: 700; }
.proto-cell { min-width: 220px; }
.proto-name { display: flex; align-items: center; gap: 8px; }
.proto-name b { font-weight: 600; font-size: 13.5px; }
.slug { display: block; font-family: var(--mono); font-size: 10.5px; color: var(--dim); margin-top: 2px; }
.watch-badge { font-size: 8.5px; letter-spacing: 0.08em; color: var(--accent); border: 1px solid rgba(55, 223, 194, 0.42); border-radius: 4px; padding: 1px 4px; }
.chips { display: flex; flex-wrap: wrap; gap: 4px; max-width: 210px; }
.chip { display: inline-block; border-radius: 5px; padding: 2px 6px; font-size: 10.5px; line-height: 1.4; white-space: nowrap; }
.chip.cat { color: #cfe3f5; background: rgba(53, 183, 255, 0.10); border: 1px solid rgba(53, 183, 255, 0.20); }
.chip.chain { color: var(--muted); background: var(--surface-3); border: 1px solid var(--border); }
.chip.more { color: var(--dim); background: transparent; border: 1px dashed var(--border-2); }
.num { font-family: var(--mono); font-variant-numeric: tabular-nums; white-space: nowrap; font-size: 12.5px; }
.pos { color: var(--pos); }
.neg { color: var(--neg); }
.implied-cell { display: flex; align-items: center; justify-content: flex-end; gap: 10px; }
.bar { width: 72px; height: 5px; border-radius: 3px; background: #1b2838; overflow: hidden; flex: none; }
.bar i { display: block; height: 100%; border-radius: 3px; background: linear-gradient(90deg, var(--accent), var(--gold)); }
.conf-cell { display: inline-flex; align-items: center; gap: 8px; justify-content: flex-end; width: 100%; }
.meter { display: inline-block; width: 72px; height: 5px; border-radius: 3px; background: #1b2838; overflow: hidden; }
.meter.small { width: 46px; }
.meter i { display: block; height: 100%; border-radius: 3px; background: var(--accent-2); }
.meter i.lv-high { background: linear-gradient(90deg, var(--accent), var(--pos)); }
