.empty h3 { font-size: 17px; }
.empty p { color: var(--muted); }
.primary { height: 36px; padding: 0 14px; border-radius: var(--radius-sm); border: 1px solid var(--accent); background: var(--accent); color: #04201b; font-weight: 600; }

/* model and method panel */
.model-panel { margin-top: 14px; }
.stats.method-stats { grid-template-columns: repeat(3, minmax(112px, 1fr)); }
.model-body { padding: 16px 18px 18px; display: grid; gap: 14px; }
.formula { font-family: var(--mono); font-size: 12.5px; color: var(--accent); background: rgba(55, 223, 194, 0.06); border: 1px solid rgba(55, 223, 194, 0.18); border-radius: var(--radius-sm); padding: 12px 14px; overflow-wrap: anywhere; }
.model-cols { display: grid; grid-template-columns: 1fr 1fr; gap: 18px; }
.mini-table h3 { font-size: 12px; color: var(--muted); letter-spacing: 0.06em; text-transform: uppercase; margin-bottom: 7px; }
.mini-table th { position: static; top: auto; padding: 6px 8px; background: transparent; border-bottom: 1px solid var(--border); }
.mini-table td { padding: 6px 8px; border-bottom: 1px solid rgba(29, 42, 56, 0.6); font-size: 12px; }
.mini-table td.accent { color: var(--accent); }
.model-note { color: var(--dim); font-size: 11.5px; line-height: 1.6; }

/* detail drawer */
.scrim { position: fixed; inset: 0; z-index: 25; background: rgba(3, 6, 10, 0.62); backdrop-filter: blur(2px); }
.scrim[hidden] { display: none; }
.detail {
  position: fixed; top: 0; right: 0; bottom: 0; z-index: 30;
  width: min(860px, 96vw); overflow-y: auto; overscroll-behavior: contain;
  background: linear-gradient(180deg, #111c28, #0a1018 70%);
  border-left: 1px solid var(--border-2); box-shadow: -30px 0 80px rgba(0, 0, 0, 0.5);
  padding: 20px 22px 30px;
}
.detail-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 16px; align-items: start; }
