.label { display: block; color: var(--dim); font-size: 10px; letter-spacing: 0.09em; text-transform: uppercase; }
.big { display: block; font-family: var(--mono); font-size: 28px; font-weight: 600; color: var(--gold); margin-top: 3px; letter-spacing: -0.02em; }
.sub { display: block; color: var(--dim); font-size: 11px; margin-top: 2px; }
.conf-block { text-align: right; min-width: 132px; }
