.detail-section { margin-top: 14px; padding-top: 11px; border-top: 1px solid var(--border); }
.detail-section h3 { font-size: 11px; letter-spacing: 0.08em; text-transform: uppercase; color: var(--muted); margin-bottom: 8px; }
.input-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 7px; }
