// Token Radar reads window.RADAR (written beside dashboard/ by main.ts) and renders the ranked
// pre-token board, filters, sortable columns, a live-token comparables view and a detail drawer.
// Every byte shown is in data.js: no fetch, no framework and no network.
(function () {
  'use strict';

  var D = window.RADAR;
  var app = document.getElementById('app');
  if (!D) {
    var miss = document.createElement('div');
    miss.className = 'shell';
    var p = document.createElement('p');
    p.className = 'lede';
    p.textContent = 'No data.js was found beside the page. Run main.ts to write one from the snapshot.';
    miss.appendChild(p);
    app.appendChild(miss);
    return;
  }

  var state = { q: '', category: 'all', chain: 'all', watch: false, sort: 'rank', dir: 1, selected: null, tab: 'board' };
  var catCounts = {};
  var chainCounts = {};
  var rowBySlug = {};
  var maxImplied = D.rows.length ? D.rows[0].implied_value_usd : 1;

  D.rows.forEach(function (r) {
    rowBySlug[r.slug] = r;
    var c = r.category || 'Other';
    catCounts[c] = (catCounts[c] || 0) + 1;
    (r.chains || []).forEach(function (ch) { chainCounts[ch] = (chainCounts[ch] || 0) + 1; });
  });

  // ---------------------------------------------------------------- formatting

  function fmtUsd(n) {
    if (n === null || n === undefined || !isFinite(n)) return 'n/a';
    var a = Math.abs(n);
    if (a >= 1e12) return '$' + (n / 1e12).toFixed(2) + 'T';
    if (a >= 1e9) return '$' + (n / 1e9).toFixed(2) + 'B';
    if (a >= 1e6) return '$' + (n / 1e6).toFixed(1) + 'M';
    if (a >= 1e3) return '$' + Math.round(n / 1e3) + 'K';
    return '$' + Math.round(n);
  }
  function fmtFull(n) {
    if (n === null || n === undefined || !isFinite(n)) return 'n/a';
    return '$' + Math.round(n).toString().replace(/\B(?=(\d{3})+(?!\d))/g, ',');
  }
  function fmtPct(n) {
    if (n === null || n === undefined || !isFinite(n)) return 'n/a';
    return (n > 0 ? '+' : '') + n.toFixed(2) + '%';
  }
  function fmtAge(d) {
    if (d === null || d === undefined) return 'unknown';
    if (d >= 730) return (d / 365).toFixed(1) + 'y';
    if (d >= 60) return Math.round(d / 30) + 'mo';
    return Math.round(d) + 'd';
  }
  function fmtRatio(n) {
    if (n === null || n === undefined || !isFinite(n)) return 'n/a';
    return n.toFixed(3) + 'x';
  }
  function rationaleFor(r) {
    var m = r.model;
    return r.name + ': ' + fmtUsd(r.tvl_usd) + ' TVL x ' + fmtRatio(m.category_multiple) + ' category (' + m.category_comparables + ' comps, median ' + fmtRatio(m.category_median) + ') x ' + fmtRatio(m.quality_adjustment) + ' chain/quality x ' + fmtRatio(m.growth_multiplier) + ' growth = about ' + fmtUsd(r.implied_value_usd);
  }
  function sensitivityLine(row) {
    var m = row.model;
    var ten = row.implied_value_usd * 0.10;
    var base = 'A 10% TVL move shifts the claim about ' + fmtUsd(ten) + ' (10%), because value is linear in TVL';
    if (m.category_median === null || !(m.category_multiple > 0)) {
      return base + '; with no raw category median, the category multiple stays at ' + fmtRatio(m.category_multiple) + '.';
    }
    var ratio = m.category_median / m.category_multiple;
    return base + '; repricing at the raw category median of ' + fmtRatio(m.category_median) + ' instead of ' + fmtRatio(m.category_multiple) + ' would multiply it by about ' + ratio.toFixed(1) + 'x.';
  }

  // ---------------------------------------------------------------- dom

  function append(node, child) {
    if (child === null || child === undefined || child === false) return;
    if (Array.isArray(child)) { child.forEach(function (c) { append(node, c); }); return; }
    if (typeof child === 'string' || typeof child === 'number') { node.appendChild(document.createTextNode(String(child))); return; }
    node.appendChild(child);
  }
  function el(tag, attrs) {
    var node = document.createElement(tag);
    if (attrs) {
